1	package main
2	
3	import (
4		"fmt"
5		"reflect"
6	
7		"github.com/anthnel/devdesk/internal/nexusbench"
8	)
9	
10	// render prints the manifests. It builds no dependency: it contacts nothing.
11	func (s *session) render() int {
12		out, err := nexusbench.Render(s.p)
13		if err != nil {
14			return s.fail(err)
15		}
16		if _, err := s.stdout.Write(out); err != nil {
17			return s.fail(err)
18		}
19		return exitOK
20	}
21	
22	// open resolves the secrets path and builds the runner and the store, in that
23	// order, before anything touches the cluster. Both are refused here when they
24	// cannot work: kubectl missing, a secrets path that git does not ignore.
25	func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
26		if s.p.SecretsPath == "" {
27			path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
28			if err != nil {
29				return nil, nil, err
30			}
31			s.p.SecretsPath = path
32		}
33		runner, err := s.d.newRunner(s.p.Context)
34		if err != nil {
35			return nil, nil, err
36		}
37		store, err := s.d.newStore(s.p.SecretsPath)
38		if err != nil {
39			return nil, nil, err
40		}
41		return runner, store, nil
42	}
43	
44	// up deploys the bench, provisions it, and only then writes the descriptor.
45	// Deploy runs the preflight of up itself.
46	func (s *session) up() int {
47		runner, store, err := s.open()
48		if err != nil {
49			return s.fail(err)
50		}
51		s.warnIfClearText()
52		deployed, err := s.d.deploy(s.ctx, runner, s.d.newProber(), s.d.clock, s.p, s.stdout)
53		if err != nil {
54			return s.fail(err)
55		}
56		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
57		if err != nil {
58			return s.fail(err)
59		}
60		return s.writeDescriptor(deployed, provisioned)
61	}
62	
63	// provision provisions a bench that is already running.
64	func (s *session) provision() int {
65		runner, store, err := s.open()
66		if err != nil {
67			return s.fail(err)
68		}
69		s.warnIfClearText()
70		pre, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpProvision)
71		if err != nil {
72			return s.fail(err)
73		}
74		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
75		if err != nil {
76			return s.fail(err)
77		}
78		return s.writeDescriptor(nexusbench.DeployResult{NodeIP: pre.NodeIP}, provisioned)
79	}
80	
81	// down deletes the bench namespace. The descriptor is left alone: it is the
82	// versioned description of the bench, not part of one instance.
83	func (s *session) down() int {
84		runner, store, err := s.open()
85		if err != nil {
86			return s.fail(err)
87		}
88		if err := s.d.destroy(s.ctx, runner, s.d.clock, store, s.p, s.stdout); err != nil {
89			return s.fail(err)
90		}
91		return exitOK
92	}
93	
94	// descriptorPath is where the descriptor is read and written.
95	func (s *session) descriptorPath() string {
96		if s.p.DescriptorPath != "" {
97			return s.p.DescriptorPath
98		}
99		return nexusbench.DescriptorPath()
100	}
101	
102	// writeDescriptor writes the descriptor of a bench that was provisioned. It is
103	// called after a successful Provision only: a partial result is never described.
104	func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult) int {
105		path := s.descriptorPath()
106		if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned)); err != nil {
107			return s.fail(err)
108		}
109		_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
110		if !describesDefaultBench(s.p) {
111			s.warn("descriptor.json now describes a non-default bench; do not commit it")
112		}
113		return exitOK
114	}
115	
116	// describesDefaultBench tells whether p is the bench the versioned descriptor
117	// describes. The timeouts, the paths and the EULA consent do not change what
118	// the bench is, so they are left out.
119	func describesDefaultBench(p nexusbench.Params) bool {
120		normalize := func(p nexusbench.Params) nexusbench.Params {
121			p.Timeout, p.DeleteTimeout = 0, 0
122			p.SecretsPath, p.DescriptorPath = "", ""
123			p.AcceptEULA = false
124			if len(p.Hosts) == 0 {
125				p.Hosts = nil
126			}
127			return p
128		}
129		return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
130	}
