1	package main
2	
3	import (
4		"flag"
5		"fmt"
6		"io"
7		"net/netip"
8		"regexp"
9		"strings"
10		"time"
11	
12		"github.com/anthnel/devdesk/internal/nexusbench"
13	)
14	
15	// Defaults of the flags that are not a NEXUS_BENCH_* parameter.
16	const (
17		loopbackHost = "127.0.0.1"
18		maxHostLen   = 253
19	)
20	
21	var (
22		// hostName is a DNS name: letters, digits, '.' and '-', no port, no path,
23		// no credentials, no whitespace.
24		hostName = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
25		// ipv6Zone is the zone of a link-local address ("eth0" in fe80::1%eth0).
26		ipv6Zone = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
27	)
28	
29	// flagKind is the type of a flag, which decides how it is registered and how
30	// its value is handed to nexusbench.FromEnv.
31	type flagKind int
32	
33	const (
34		kindString flagKind = iota
35		kindInt
36		kindDuration
37		kindBool
38		// kindConsent is a boolean whose true is the exact word "yes", the only
39		// value nexusbench accepts for NEXUS_BENCH_ACCEPT_EULA.
40		kindConsent
41	)
42	
43	// paramFlag is one flag that stands for one NEXUS_BENCH_* variable.
44	type paramFlag struct {
45		name  string
46		env   string
47		kind  flagKind
48		usage string
49	}
50	
51	// commonFlags are accepted by every subcommand.
52	func commonFlags() []paramFlag {
53		d := nexusbench.Defaults()
54		return []paramFlag{
55			{"context", "NEXUS_BENCH_CONTEXT", kindString, "kubectl context of the cluster (default " + d.Context + ")"},
56			{"namespace", "NEXUS_BENCH_NAMESPACE", kindString, "namespace of the bench, which down deletes (default " + d.Namespace + ")"},
57			{"http-nodeport", "NEXUS_BENCH_HTTP_NODEPORT", kindInt, fmt.Sprintf("NodePort of the REST API and the UI (default %d)", d.HTTPNodePort)},
58			{"docker-nodeport", "NEXUS_BENCH_DOCKER_NODEPORT", kindInt, fmt.Sprintf("NodePort of the Docker connector (default %d)", d.DockerNodePort)},
59			{"cpu-request", "NEXUS_BENCH_CPU_REQUEST", kindString, "CPU request (default " + d.CPURequest + ")"},
60			{"cpu-limit", "NEXUS_BENCH_CPU_LIMIT", kindString, "CPU limit (default " + d.CPULimit + ")"},
61			{"memory-request", "NEXUS_BENCH_MEMORY_REQUEST", kindString, "memory request (default " + d.MemoryRequest + ")"},
62			{"memory-limit", "NEXUS_BENCH_MEMORY_LIMIT", kindString, "memory limit (default " + d.MemoryLimit + ")"},
63			{"storage-size", "NEXUS_BENCH_STORAGE_SIZE", kindString, "size of the data volume (default " + d.StorageSize + ")"},
64			{"jvm-opts", "NEXUS_BENCH_JVM_OPTS", kindString, "JVM options of Nexus (default " + d.JVMOpts + ")"},
65			{"image", "NEXUS_BENCH_IMAGE", kindString, "Nexus image, without the tag (default " + d.Image + ")"},
66			{"image-tag", "NEXUS_BENCH_IMAGE_TAG", kindString, "Nexus image tag (default " + d.ImageTag + ")"},
67			{"upstream-url", "NEXUS_BENCH_UPSTREAM_URL", kindString, "upstream of the proxy repository (default http://bench-upstream.<namespace>.svc.cluster.local:5000)"},
68			{"anonymous", "NEXUS_BENCH_ANONYMOUS", kindBool, "enable anonymous access, --anonymous=false to disable (default true)"},
69			{"hosts", "NEXUS_BENCH_HOSTS", kindString, "comma-separated hosts the NodePorts are tried on (default 127.0.0.1 and the node address)"},
70			{"timeout", "NEXUS_BENCH_TIMEOUT", kindDuration, "how long up waits for Nexus (default " + d.Timeout.String() + ")"},
71			{"delete-timeout", "NEXUS_BENCH_DELETE_TIMEOUT", kindDuration, "how long down waits for the namespace to go (default " + d.DeleteTimeout.String() + ")"},
72			{"secrets", "NEXUS_BENCH_SECRETS", kindString, "secrets file, outside the repository (default under $XDG_STATE_HOME/devdesk/nexus-bench)"},
73			{"descriptor", "NEXUS_BENCH_DESCRIPTOR", kindString, "descriptor file (default internal/nexusbench/descriptor.json)"},
74		}
75	}
76	
77	// provisionFlags are accepted by the subcommands that provision Nexus.
78	func provisionFlags() []paramFlag {
79		return []paramFlag{
80			{"accept-eula", "NEXUS_BENCH_ACCEPT_EULA", kindConsent, "accept the Nexus Community Edition EULA on your behalf: read it first (default false; the variable counts only as the exact value yes)"},
81		}
82	}
83	
84	// restHostFlag names the flag that picks the host the admin credentials are sent to.
85	const restHostFlag = "rest-host"
86	
87	// flagSet is the flags of one subcommand.
88	type flagSet struct {
89		fs       *flag.FlagSet
90		specs    map[string]paramFlag
91		restHost *string
92	}
93	
94	// newFlagSet registers the flags of a subcommand. It prints nothing by itself:
95	// the caller reports a parse error on stderr and the help on stdout.
96	func newFlagSet(name string, provisions bool) *flagSet {
97		fs := flag.NewFlagSet("nexus-bench "+name, flag.ContinueOnError)
98		fs.SetOutput(io.Discard)
99		fs.Usage = func() {}
100		set := &flagSet{fs: fs, specs: map[string]paramFlag{}}
101		specs := commonFlags()
102		if provisions {
103			specs = append(specs, provisionFlags()...)
104		}
105		for _, spec := range specs {
106			set.specs[spec.name] = spec
107			switch spec.kind {
108			case kindString:
109				fs.String(spec.name, "", spec.usage)
110			case kindInt:
111				fs.Int(spec.name, 0, spec.usage)
112			case kindDuration:
113				fs.Duration(spec.name, time.Duration(0), spec.usage)
114			case kindBool, kindConsent:
115				fs.Bool(spec.name, false, spec.usage)
116			}
117		}
118		if provisions {
119			set.restHost = fs.String(restHostFlag, "", "host the REST API is reached on, and so the host the admin credentials are sent to (default "+loopbackHost+"); another host sends them in clear text")
120		}
121		return set
122	}
123	
124	// parse reads args. It returns flag.ErrHelp for -h and --help, and an error for
125	// an unknown flag, a value of the wrong type or an argument that is not a flag.
126	func (s *flagSet) parse(args []string) error {
127		if err := s.fs.Parse(args); err != nil {
128			return err
129		}
130		if s.fs.NArg() > 0 {
131			return fmt.Errorf("unexpected argument %q", s.fs.Arg(0))
132		}
133		return nil
134	}
135	
136	// printHelp writes the flags and their default to w.
137	func (s *flagSet) printHelp(w io.Writer) {
138		s.fs.SetOutput(w)
139		s.fs.PrintDefaults()
140		s.fs.SetOutput(io.Discard)
141	}
142	
143	// overlay returns getenv with every flag that was given laid over its
144	// NEXUS_BENCH_* variable: nexusbench.FromEnv then applies "flag, then variable,
145	// then default" in one place, with the same parsing and the same follow-the-
146	// namespace rule for the upstream URL.
147	func (s *flagSet) overlay(getenv func(string) string) func(string) string {
148		given := map[string]string{}
149		s.fs.Visit(func(f *flag.Flag) {
150			spec, ok := s.specs[f.Name]
151			if !ok {
152				return
153			}
154			value := f.Value.String()
155			if spec.kind == kindConsent {
156				value = map[bool]string{true: "yes", false: "no"}[value == "true"]
157			}
158			given[spec.env] = value
159		})
160		return func(name string) string {
161			if v, ok := given[name]; ok {
162				return v
163			}
164			return getenv(name)
165		}
166	}
167	
168	// restHostGiven returns the --rest-host value and whether it was set.
169	func (s *flagSet) restHostGiven() (string, bool) {
170		if s.restHost == nil {
171			return "", false
172		}
173		given := false
174		s.fs.Visit(func(f *flag.Flag) {
175			if f.Name == restHostFlag {
176				given = true
177			}
178		})
179		return *s.restHost, given
180	}
181	
182	// resolveParams returns the validated parameters of a run: defaults, then the
183	// NEXUS_BENCH_* variables, then the flags.
184	func (s *flagSet) resolveParams(getenv func(string) string) (nexusbench.Params, error) {
185		p, err := nexusbench.FromEnv(nexusbench.Defaults(), s.overlay(getenv))
186		if err != nil {
187			return p, err
188		}
189		return p, p.Validate()
190	}
191	
192	// validateRESTHost refuses what is not a host name or an IP address: a port, a
193	// path, a scheme, credentials or whitespace would change where the admin
194	// credentials go.
195	func validateRESTHost(host string) error {
196		if host == "" || len(host) > maxHostLen {
197			return fmt.Errorf("--%s: %q is not a host name or an IP address", restHostFlag, host)
198		}
199		if addr, ok := hostAddress(host); ok {
200			if zone := addr.Zone(); zone != "" && !ipv6Zone.MatchString(zone) {
201				return fmt.Errorf("--%s: %q has an unusable IPv6 zone", restHostFlag, host)
202			}
203			return nil
204		}
205		if !hostName.MatchString(host) {
206			return fmt.Errorf("--%s: %q is not a host name or an IP address (no port, scheme, path or credentials)", restHostFlag, host)
207		}
208		return nil
209	}
210	
211	// hostAddress parses host as an IP address, with or without the brackets of an
212	// IPv6 literal.
213	func hostAddress(host string) (netip.Addr, bool) {
214		if len(host) > 1 && strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
215			host = host[1 : len(host)-1]
216		}
217		addr, err := netip.ParseAddr(host)
218		return addr, err == nil
219	}
220	
221	// isLoopbackHost tells whether host stays on this machine.
222	func isLoopbackHost(host string) bool {
223		if strings.EqualFold(host, "localhost") {
224			return true
225		}
226		addr, ok := hostAddress(host)
227		return ok && addr.Unmap().IsLoopback()
228	}
