1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"strconv"
8		"strings"
9	
10		"github.com/anthnel/devdesk/internal/nexusbench"
11	)
12	
13	// nexusPodSelector is the label of the Nexus pod (see 20-deployment.yaml.tmpl).
14	const nexusPodSelector = "app.kubernetes.io/name=nexus"
15	
16	// status reads the cluster and the descriptor and reports; it changes nothing.
17	// A pod that is missing or a Nexus that does not answer is a finding, not a
18	// failure: the exit code is 1 only when the cluster cannot be read at all.
19	func (s *session) status() int {
20		runner, err := s.d.newRunner(s.p.Context)
21		if err != nil {
22			return s.fail(err)
23		}
24		if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpStatus); err != nil {
25			return s.fail(err)
26		}
27		pod := readPod(s, runner)
28		if err := s.ctx.Err(); err != nil {
29			return s.fail(err)
30		}
31		base := s.restURL()
32		rest := "ready"
33		if err := s.d.newProber().Ready(s.ctx, base); err != nil {
34			// The error is not shown: the text of a failed call is not trusted.
35			rest = "not ready"
36		}
37		if err := s.ctx.Err(); err != nil {
38			return s.fail(err)
39		}
40		_, _ = fmt.Fprintf(s.stdout, "bench: namespace %s, context %s\n", s.p.Namespace, s.p.Context)
41		_, _ = fmt.Fprintf(s.stdout, "pod: %s\n", pod)
42		_, _ = fmt.Fprintf(s.stdout, "rest: %s (%s)\n", rest, base)
43		_, _ = fmt.Fprintf(s.stdout, "descriptor: %s\n", s.describeDescriptor())
44		return exitOK
45	}
46	
47	// podList is the part of `kubectl get pods -o json` the report reads.
48	type podList struct {
49		Items []struct {
50			Metadata struct {
51				Name              string `json:"name"`
52				DeletionTimestamp string `json:"deletionTimestamp"`
53			} `json:"metadata"`
54			Status struct {
55				Phase             string `json:"phase"`
56				ContainerStatuses []struct {
57					Ready        bool `json:"ready"`
58					RestartCount int  `json:"restartCount"`
59				} `json:"containerStatuses"`
60			} `json:"status"`
61		} `json:"items"`
62	}
63	
64	// readPod describes the Nexus pod in one line: its phase, name, readiness and restarts.
65	func readPod(s *session, r nexusbench.Runner) string {
66		stdout, _, err := r.Run(s.ctx, nil, "get", "pods", "-n", s.p.Namespace, "-l", nexusPodSelector, "-o", "json", "--request-timeout=10s")
67		if err != nil {
68			return "unknown (kubectl get pods failed)"
69		}
70		var list podList
71		if err := json.Unmarshal(stdout, &list); err != nil {
72			return "unknown (kubectl get pods returned something unreadable)"
73		}
74		if len(list.Items) == 0 {
75			return "not found"
76		}
77		item := list.Items[0]
78		phase := strings.ToLower(item.Status.Phase)
79		if item.Metadata.DeletionTimestamp != "" {
80			phase = "terminating"
81		}
82		if phase == "" {
83			phase = "unknown"
84		}
85		ready, restarts := 0, 0
86		for _, c := range item.Status.ContainerStatuses {
87			if c.Ready {
88				ready++
89			}
90			restarts += c.RestartCount
91		}
92		line := fmt.Sprintf("%s (%s, %d/%d ready, %d restarts", phase, item.Metadata.Name, ready, len(item.Status.ContainerStatuses), restarts)
93		if len(list.Items) > 1 {
94			line += fmt.Sprintf(", %d more pods", len(list.Items)-1)
95		}
