117	// descriptorDiffs lists the fields of the descriptor that the parameters of
118	// this run would write differently. The hosts and the versions are left out:
119	// they come from the cluster, not from the parameters.
120	func descriptorDiffs(d nexusbench.Descriptor, p nexusbench.Params) []string {
121		want := nexusbench.BuildDescriptor(p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{})
122		fields := []struct{ name, got, want string }{
123			{"context", d.KubeContext, want.KubeContext},
124			{"namespace", d.Namespace, want.Namespace},
125			{"image", d.Image, want.Image},
126			{"http nodePort", strconv.Itoa(d.REST.NodePort), strconv.Itoa(want.REST.NodePort)},
127			{"docker nodePort", dockerPort(d), dockerPort(want)},
128			{"upstream URL", upstreamURL(d), upstreamURL(want)},
129			{"anonymous access", anonymous(d), anonymous(want)},
130		}
131		var diffs []string
132		for _, f := range fields {
133			if f.got != f.want {
134				diffs = append(diffs, fmt.Sprintf("%s: descriptor %s, current %s", f.name, f.got, f.want))
135			}
136		}
137		return diffs
138	}
