351				t.Fatalf("%s: %v", op, err)
352			}
353			out := make([]string, 0, len(rows))
354			for _, row := range rows {
355				s, _ := row[field].(string)
356				out = append(out, s)
357			}
358			slices.Sort(out)
359			return out
360		}
361		return benchSnapshot{
362			Repositories: names("list the repositories", restAPI+"/repositories", "name"),
