var _ nexusbench.Prober = (*fakeProber)(nil)

func (p *fakeProber) Ready(_ context.Context, baseURL string) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.urls = append(p.urls, baseURL)
	return p.err
}

